// Env is generated by `wrangler types` (see worker-configuration.d.ts):
// bindings + vars come from wrangler.jsonc. This layer adds the runtime
// secrets that live in the secrets store, never in config.
export type Env = Cloudflare.Env & {
  VAPID_PUBLIC_KEY?: string;
  VAPID_PRIVATE_KEY?: string;
  VAPID_SUBJECT?: string;
};
